15	    private static void shouldGenerateExpectedTraversalOrderCodes() {
16	        assertListEquals(
17	                Arrays.asList("0", "100", "101", "1100", "1101", "111"),
18	                HuffmanCoding.huffmanCodes("abcdef", new int[]{5, 9, 12, 13, 16, 45}),
19	                "legacy API should preserve traversal-order output"
20	        );
21	    }
22	
23	    private static void shouldGenerateExpectedSymbolOrderCodes() {
24	        assertListEquals(
25	                Arrays.asList("1100", "1101", "100", "101", "111", "0"),
26	                HuffmanCoding.huffmanCodesBySymbolOrder("abcdef", new int[]{5, 9, 12, 13, 16, 45}),
27	                "symbol-order API should align codes with the input symbol positions"
28	        );
29	    }
