55	    private static void shouldRejectNullFrequencies() {
56	        assertThrows(
57	                NullPointerException.class,
58	                () -> HuffmanCoding.huffmanCodes((int[]) null),
59	                "null frequencies should be rejected"
60	        );
61	    }
62	
63	    private static void shouldRejectNegativeFrequencies() {
64	        assertThrows(
65	                IllegalArgumentException.class,
66	                () -> HuffmanCoding.huffmanCodes(new int[]{2, -1, 3}),
67	                "negative frequencies should be rejected"
68	        );
69	    }
