  1	import java.util.ArrayList;
  2	import java.util.Arrays;
  3	import java.util.Comparator;
  4	import java.util.List;
  5	import java.util.Objects;
  6	import java.util.PriorityQueue;
  7	
  8	public class HuffmanCoding {
  9	    private static final String SINGLE_SYMBOL_CODE = "0";
 10	    private static final String SAMPLE_SYMBOLS = "abcdef";
 11	    private static final int[] SAMPLE_FREQUENCIES = {5, 9, 12, 13, 16, 45};
 12	
 13	    private enum CodeOrder {
 14	        TRAVERSAL,
 15	        SYMBOL
 16	    }
 17	
 18	    static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
 19	        validateSymbols(symbols);
 20	        validateFrequencyCount(symbols.length(), frequencies);
 21	        return HuffmanTree.fromFrequencies(frequencies).buildCodes(symbols.length(), CodeOrder.TRAVERSAL);
 22	    }
 23	
 24	    static ArrayList<String> huffmanCodes(int[] frequencies) {
 25	        validateFrequencies(frequencies);
 26	        return HuffmanTree.fromFrequencies(frequencies)
 27	                .buildCodes(frequencies.length, CodeOrder.TRAVERSAL);
 28	    }
 29	
 30	    static ArrayList<String> huffmanCodesBySymbolOrder(String symbols, int[] frequencies) {
 31	        validateSymbols(symbols);
 32	        validateFrequencyCount(symbols.length(), frequencies);
 33	        return HuffmanTree.fromFrequencies(frequencies).buildCodes(symbols.length(), CodeOrder.SYMBOL);
 34	    }
 35	
 36	    private static void validateSymbols(String symbols) {
 37	        Objects.requireNonNull(symbols, "symbols must not be null");
 38	    }
 39	
 40	    private static void validateFrequencies(int[] frequencies) {
 41	        Objects.requireNonNull(frequencies, "frequencies must not be null");
 42	        for (int frequency : frequencies) {
 43	            if (frequency < 0) {
 44	                throw new IllegalArgumentException("frequencies must be non-negative");
 45	            }
 46	        }
 47	    }
 48	
 49	    private static void validateFrequencyCount(int symbolCount, int[] frequencies) {
 50	        validateFrequencies(frequencies);
 51	        if (symbolCount != frequencies.length) {
 52	            throw new IllegalArgumentException("symbols and frequencies must be the same length");
 53	        }
 54	    }
 55	
 56	    private static void printCodes(List<String> codes) {
 57	        System.out.print(String.join(" ", codes));
 58	    }
 59	
 60	    public static void main(String[] args) {
 61	        ArrayList<String> codes = huffmanCodes(SAMPLE_SYMBOLS, SAMPLE_FREQUENCIES);
 62	        printCodes(codes);
 63	    }
 64	
 65	    private static final class HuffmanTree {
 66	        private static final Comparator<Node> NODE_ORDER =
 67	                Comparator.comparingInt((Node node) -> node.frequency)
 68	                        .thenComparingInt(node -> node.sortOrder);
 69	
 70	        private final Node root;
 71	
 72	        private HuffmanTree(Node root) {
 73	            this.root = root;
 74	        }
 75	
 76	        private static HuffmanTree fromFrequencies(int[] frequencies) {
 77	            if (frequencies.length == 0) {
 78	                return new HuffmanTree(null);
 79	            }
 80	
 81	            PriorityQueue<Node> queue = new PriorityQueue<>(NODE_ORDER);
 82	            for (int i = 0; i < frequencies.length; i++) {
 83	                queue.add(new Node(frequencies[i], i));
 84	            }
 85	
 86	            while (queue.size() > 1) {
 87	                Node left = queue.poll();
 88	                Node right = queue.poll();
 89	                queue.add(new Node(left, right));
 90	            }
 91	
 92	            return new HuffmanTree(queue.peek());
 93	        }
 94	
 95	        private ArrayList<String> buildCodes(int symbolCount, CodeOrder codeOrder) {
 96	            if (symbolCount == 0) {
 97	                return new ArrayList<>();
 98	            }
 99	
100	            CodeAccumulator accumulator = codeOrder == CodeOrder.SYMBOL
101	                    ? new SymbolOrderAccumulator(symbolCount)
102	                    : new TraversalOrderAccumulator();
103	            collectCodes(root, new StringBuilder(), accumulator);
104	            return accumulator.toList();
105	        }
106	
107	        private void collectCodes(Node node, StringBuilder path, CodeAccumulator accumulator) {
108	            if (node == null) {
109	                return;
110	            }
111	
112	            if (node.isLeaf()) {
113	                accumulator.add(node.symbolIndex, path.length() == 0 ? SINGLE_SYMBOL_CODE : path.toString());
114	                return;
115	            }
116	
117	            path.append('0');
118	            collectCodes(node.left, path, accumulator);
119	            path.deleteCharAt(path.length() - 1);
120	
121	            path.append('1');
122	            collectCodes(node.right, path, accumulator);
123	            path.deleteCharAt(path.length() - 1);
124	        }
125	
126	        private interface CodeAccumulator {
127	            void add(int symbolIndex, String code);
128	
129	            ArrayList<String> toList();
130	        }
131	
132	        private static final class TraversalOrderAccumulator implements CodeAccumulator {
133	            private final ArrayList<String> codes = new ArrayList<>();
134	
135	            @Override
136	            public void add(int symbolIndex, String code) {
137	                codes.add(code);
138	            }
139	
140	            @Override
141	            public ArrayList<String> toList() {
142	                return codes;
143	            }
144	        }
145	
146	        private static final class SymbolOrderAccumulator implements CodeAccumulator {
147	            private final String[] codesBySymbol;
148	
149	            private SymbolOrderAccumulator(int symbolCount) {
150	                codesBySymbol = new String[symbolCount];
151	            }
152	
153	            @Override
154	            public void add(int symbolIndex, String code) {
155	                codesBySymbol[symbolIndex] = code;
156	            }
157	
158	            @Override
159	            public ArrayList<String> toList() {
160	                return new ArrayList<>(Arrays.asList(codesBySymbol));
161	            }
162	        }
163	
164	        private static final class Node {
165	            private final int frequency;
166	            private final int sortOrder;
167	            private final int symbolIndex;
168	            private final Node left;
169	            private final Node right;
170	
171	            private Node(int frequency, int symbolIndex) {
172	                this(frequency, symbolIndex, symbolIndex, null, null);
173	            }
174	
175	            private Node(Node left, Node right) {
176	                this(
177	                        left.frequency + right.frequency,
178	                        Math.min(left.sortOrder, right.sortOrder),
179	                        -1,
180	                        left,
181	                        right
182	                );
183	            }
184	
185	            private Node(int frequency, int sortOrder, int symbolIndex, Node left, Node right) {
186	                this.frequency = frequency;
187	                this.sortOrder = sortOrder;
188	                this.symbolIndex = symbolIndex;
189	                this.left = left;
190	                this.right = right;
191	            }
192	
193	            private boolean isLeaf() {
194	                return left == null && right == null;
195	            }
196	        }
197	    }
198	}
